def _security_upgrade() -> None:
    for table in TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(f'''
            CREATE POLICY tenant_isolation ON {table}
            USING (organisation_id = app_current_org())
            WITH CHECK (organisation_id = app_current_org())
        ''')

    op.execute('''
        -- The movement ledger is the only way stock changes. Each movement is applied to its
        -- batch; the batch's CHECK (quantity_remaining >= 0) rejects negative stock.
        CREATE FUNCTION stock_movements_apply() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE b stock_batches%ROWTYPE;
        BEGIN
            SELECT * INTO b FROM stock_batches WHERE id = NEW.batch_id FOR UPDATE;
            IF b.item_id <> NEW.item_id OR b.branch_id <> NEW.branch_id THEN
                RAISE EXCEPTION 'stock movement does not match its batch';
            END IF;
            UPDATE stock_batches SET quantity_remaining = quantity_remaining + NEW.quantity,
                updated_at = now() WHERE id = NEW.batch_id;
            RETURN NEW;
        END $$;
        CREATE TRIGGER stock_movements_apply AFTER INSERT ON stock_movements
            FOR EACH ROW EXECUTE FUNCTION stock_movements_apply();

        CREATE FUNCTION stock_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME; END $$;
        CREATE TRIGGER stock_movements_append_only
            BEFORE UPDATE OR DELETE OR TRUNCATE ON stock_movements
            FOR EACH STATEMENT EXECUTE FUNCTION stock_append_only();

        -- Batches start empty (their receipt movement fills them), keep their identity, and
        -- change quantity only from the movement trigger. They are never deleted.
        CREATE FUNCTION stock_batches_guard() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP = 'DELETE' THEN
                RAISE EXCEPTION 'stock batches cannot be deleted';
            END IF;
            IF TG_OP = 'INSERT' THEN
                IF NEW.quantity_remaining <> 0 THEN
                    RAISE EXCEPTION 'stock is added through stock movements';
                END IF;
                RETURN NEW;
            END IF;
            IF (NEW.organisation_id, NEW.item_id, NEW.branch_id, NEW.batch_number,
                NEW.expiry_date, NEW.unit_cost, NEW.quantity_received, NEW.received_at,
                NEW.supplier_id, NEW.purchase_order_id)
               IS DISTINCT FROM
               (OLD.organisation_id, OLD.item_id, OLD.branch_id, OLD.batch_number,
                OLD.expiry_date, OLD.unit_cost, OLD.quantity_received, OLD.received_at,
                OLD.supplier_id, OLD.purchase_order_id) THEN
                RAISE EXCEPTION 'stock batch details cannot be changed';
            END IF;
            IF NEW.quantity_remaining <> OLD.quantity_remaining AND pg_trigger_depth() < 2 THEN
                RAISE EXCEPTION 'stock is changed through stock movements';
            END IF;
            RETURN NEW;
        END $$;
        CREATE TRIGGER stock_batches_integrity BEFORE INSERT OR UPDATE OR DELETE ON stock_batches
            FOR EACH ROW EXECUTE FUNCTION stock_batches_guard();

        -- Purchase order lines: received quantities only grow; received lines stay.
        CREATE FUNCTION purchase_order_lines_guard() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP = 'DELETE' THEN
                IF OLD.quantity_received > 0 THEN
                    RAISE EXCEPTION 'received purchase order lines cannot be deleted';
                END IF;
                RETURN OLD;
            END IF;
            IF NEW.quantity_received < OLD.quantity_received THEN
                RAISE EXCEPTION 'received quantities cannot be reduced';
            END IF;
            IF OLD.quantity_received > 0 AND (NEW.item_id, NEW.unit_cost, NEW.quantity_ordered)
               IS DISTINCT FROM (OLD.item_id, OLD.unit_cost, OLD.quantity_ordered) THEN
                RAISE EXCEPTION 'received purchase order lines cannot be changed';
            END IF;
            RETURN NEW;
        END $$;
        CREATE TRIGGER purchase_order_lines_integrity
            BEFORE UPDATE OR DELETE ON purchase_order_lines
            FOR EACH ROW EXECUTE FUNCTION purchase_order_lines_guard();

        -- Nobody is rostered on two overlapping shifts, or has overlapping open leave.
        ALTER TABLE staff_shifts ADD CONSTRAINT ex_shifts_no_overlap
            EXCLUDE USING gist (membership_id WITH =, tstzrange(starts_at, ends_at) WITH &&)
            WHERE (status = 'scheduled');
        ALTER TABLE staff_leave ADD CONSTRAINT ex_leave_no_overlap
            EXCLUDE USING gist (membership_id WITH =, daterange(starts_on, ends_on, '[]') WITH &&)
            WHERE (status IN ('requested', 'approved'));
    ''')

    role = get_settings().app_db_role
    op.execute(f'''
        DO $$
        BEGIN
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{role}') THEN
                GRANT SELECT, INSERT, UPDATE ON inventory_items, suppliers, purchase_orders,
                    purchase_order_lines, stock_batches, staff_shifts, staff_leave TO {role};
                GRANT DELETE ON purchase_order_lines TO {role};  -- draft lines only
                GRANT SELECT, INSERT ON stock_movements TO {role};
            END IF;
        END $$;
    ''')


